-- C07 read models from immutable business documents. No financial posting or balance copies.
CREATE TABLE sales.order_attributions(company_id uuid NOT NULL,order_id uuid NOT NULL,version bigint NOT NULL CHECK(version>0),salesperson_id uuid REFERENCES identity.users(id),basis text NOT NULL CHECK(basis IN('QUOTE_AUTHOR','LEGACY_QUOTE_AUTHOR','DIRECT_UNASSIGNED','EXPLICIT')),reason text NOT NULL CHECK(length(reason)BETWEEN 1 AND 2000),created_by uuid NOT NULL REFERENCES identity.users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,order_id,version),FOREIGN KEY(company_id,order_id)REFERENCES sales.orders(company_id,id));
CREATE TABLE sales.line_dimensions(company_id uuid NOT NULL,order_line_id uuid NOT NULL,base_uom_id uuid NOT NULL,base_unit_code text NOT NULL,sku text NOT NULL,product_name text NOT NULL,basis text NOT NULL CHECK(basis IN('ORDER_LINE','LEGACY_AT_CUTOVER')),PRIMARY KEY(company_id,order_line_id),FOREIGN KEY(company_id,order_line_id)REFERENCES sales.order_lines(company_id,id),FOREIGN KEY(company_id,base_uom_id)REFERENCES catalog.uoms(company_id,id));
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['order_attributions','line_dimensions']LOOP EXECUTE format('ALTER TABLE sales.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE sales.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY company_scope ON sales.%I USING(company_id=core.current_company())WITH CHECK(company_id=core.current_company())',t);EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON sales.%I FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation()',t);END LOOP;END$$;
CREATE FUNCTION sales.capture_order_attribution()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN INSERT INTO sales.order_attributions(company_id,order_id,version,salesperson_id,basis,reason,created_by)VALUES(NEW.company_id,NEW.id,1,(SELECT created_by FROM sales.quotes WHERE company_id=NEW.company_id AND id=NEW.source_quote_id),CASE WHEN NEW.source_quote_id IS NULL THEN'DIRECT_UNASSIGNED'ELSE'QUOTE_AUTHOR'END,'Frozen order provenance',NEW.created_by);RETURN NEW;END$$;
CREATE FUNCTION sales.capture_line_dimension()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN INSERT INTO sales.line_dimensions(company_id,order_line_id,base_uom_id,base_unit_code,sku,product_name,basis)SELECT NEW.company_id,NEW.id,p.base_uom_id,u.code,coalesce(nullif(NEW.snapshot->>'sku',''),p.sku),coalesce(nullif(NEW.snapshot->>'name',''),p.name),'ORDER_LINE'FROM catalog.products p JOIN catalog.uoms u ON u.company_id=p.company_id AND u.id=p.base_uom_id WHERE p.company_id=NEW.company_id AND p.id=NEW.product_id;RETURN NEW;END$$;
CREATE TRIGGER capture_attribution AFTER INSERT ON sales.orders FOR EACH ROW EXECUTE FUNCTION sales.capture_order_attribution();
CREATE TRIGGER capture_dimension AFTER INSERT ON sales.order_lines FOR EACH ROW EXECUTE FUNCTION sales.capture_line_dimension();
DO $$DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);
 INSERT INTO sales.order_attributions(company_id,order_id,version,salesperson_id,basis,reason,created_by)SELECT c,o.id,1,q.created_by,CASE WHEN q.id IS NULL THEN'DIRECT_UNASSIGNED'ELSE'LEGACY_QUOTE_AUTHOR'END,'Legacy immutable quote provenance; direct orders remain unassigned',o.created_by FROM sales.orders o LEFT JOIN sales.quotes q ON q.company_id=o.company_id AND q.id=o.source_quote_id WHERE o.company_id=c;
 INSERT INTO sales.line_dimensions(company_id,order_line_id,base_uom_id,base_unit_code,sku,product_name,basis)SELECT c,l.id,p.base_uom_id,u.code,coalesce(nullif(l.snapshot->>'sku',''),p.sku),coalesce(nullif(l.snapshot->>'name',''),p.name),'LEGACY_AT_CUTOVER'FROM sales.order_lines l JOIN catalog.products p ON p.company_id=l.company_id AND p.id=l.product_id JOIN catalog.uoms u ON u.company_id=p.company_id AND u.id=p.base_uom_id WHERE l.company_id=c;
 SET CONSTRAINTS ALL IMMEDIATE;SET CONSTRAINTS ALL DEFERRED;END LOOP;PERFORM set_config('htt.company_id','',true);END$$;
INSERT INTO identity.permissions(code,description)VALUES('reports.sales.read','Read current authorized customer sales facts and trends'),('reports.sales.all','Read sales across authorized company customers'),('reports.sales.reconcile','Inspect company sales and fulfilment cost GL bridges'),('sales.attribution.assign','Assign an order salesperson before first invoice');
CREATE FUNCTION identity.seed_sales_analytics_roles(c uuid)RETURNS void LANGUAGE sql SET search_path=pg_catalog AS $$INSERT INTO identity.role_permissions(company_id,role_id,permission_code)SELECT c,r.id,p.code FROM identity.roles r CROSS JOIN identity.permissions p WHERE r.company_id=c AND((r.code IN('ADMIN','OFFICE','FINANCE','SALES')AND p.code='reports.sales.read')OR(r.code IN('ADMIN','OFFICE','FINANCE')AND p.code='reports.sales.all')OR(r.code IN('ADMIN','FINANCE')AND p.code='reports.sales.reconcile')OR(r.code IN('ADMIN','OFFICE')AND p.code='sales.attribution.assign'))ON CONFLICT DO NOTHING$$;
DO $$DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_sales_analytics_roles(c);END LOOP;PERFORM set_config('htt.company_id','',true);END$$;
CREATE FUNCTION sales.require_analytics_customer(p_customer uuid)RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_mobile('reports.sales.read');PERFORM crm.require_mobile('customers.read');IF p_customer IS NOT NULL AND NOT crm.mobile_customer_visible(p_customer)THEN RAISE EXCEPTION 'Sales customer scope denied' USING ERRCODE='42501';END IF;END$$;
CREATE FUNCTION sales.analytics_visible(p_customer uuid)RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT crm.mobile_permission('reports.sales.read')AND crm.mobile_customer_visible(p_customer)$$;
CREATE FUNCTION sales.attribution_view(p_order uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE cust uuid;BEGIN SELECT customer_id INTO cust FROM sales.orders WHERE company_id=core.current_company()AND id=p_order;IF NOT FOUND THEN RAISE EXCEPTION 'Order unavailable' USING ERRCODE='HT404';END IF;PERFORM sales.require_analytics_customer(cust);RETURN(SELECT jsonb_build_object('orderId',order_id,'salespersonId',salesperson_id,'basis',basis,'version',version,'reason',reason,'createdAt',created_at,'frozen',EXISTS(SELECT 1 FROM sales.invoices WHERE company_id=core.current_company()AND order_id=p_order))FROM sales.order_attributions WHERE company_id=core.current_company()AND order_id=p_order ORDER BY version DESC LIMIT 1);END$$;
CREATE FUNCTION sales.assign_attribution(p_order uuid,p_version bigint,p_user uuid,p_reason text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE o sales.orders;v bigint;BEGIN PERFORM crm.require_mobile('sales.attribution.assign');PERFORM sales.attribution_view(p_order);PERFORM 1 FROM platform.documents WHERE company_id=core.current_company()AND id=p_order FOR UPDATE;
 PERFORM crm.require_mobile('sales.attribution.assign');SELECT*INTO o FROM sales.orders WHERE company_id=core.current_company()AND id=p_order;PERFORM sales.require_analytics_customer(o.customer_id);SELECT max(version)INTO v FROM sales.order_attributions WHERE company_id=o.company_id AND order_id=o.id;
 IF v IS DISTINCT FROM p_version OR EXISTS(SELECT 1 FROM sales.invoices WHERE company_id=o.company_id AND order_id=o.id)OR o.cancelled_at IS NOT NULL THEN RAISE EXCEPTION 'Order attribution is stale or already frozen by invoicing/cancellation' USING ERRCODE='HR409';END IF;
 IF p_user IS NULL OR NOT crm.member_permission(p_user,'reports.sales.read')OR NOT crm.member_customer(p_user,o.customer_id)THEN RAISE EXCEPTION 'Active authorized salesperson required' USING ERRCODE='42501';END IF;IF coalesce(length(btrim(p_reason)),0)NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Assignment reason required' USING ERRCODE='HR422';END IF;
 INSERT INTO sales.order_attributions(company_id,order_id,version,salesperson_id,basis,reason,created_by)VALUES(o.company_id,o.id,v+1,p_user,'EXPLICIT',btrim(p_reason),core.current_actor());RETURN sales.attribution_view(p_order);END$$;
CREATE VIEW sales.net_sales_source WITH(security_invoker=true)AS
 SELECT i.company_id,'INVOICE:'||il.id::text AS fact_id,'INVOICE'::text AS event_type,i.id AS document_id,il.id AS source_line_id,i.id AS invoice_id,il.id AS invoice_line_id,o.id AS order_id,ol.id AS order_line_id,o.customer_id,o.customer_branch_id AS branch_id,o.warehouse_id,ol.product_id,dim.base_uom_id,dim.base_unit_code,dim.sku,dim.product_name,a.salesperson_id,a.version AS attribution_version,a.basis AS attribution_basis,d.business_date AS posting_date,il.quantity AS selling_quantity,il.base_quantity AS base_quantity,il.quantity AS original_invoice_quantity,il.base_quantity AS original_invoice_base_quantity,il.net,il.tax,il.gross,NULL::uuid AS return_line_id,i.created_at AS recorded_at
 FROM sales.invoice_lines il JOIN sales.invoices i ON i.company_id=il.company_id AND i.id=il.invoice_id JOIN sales.orders o ON o.company_id=i.company_id AND o.id=i.order_id JOIN sales.order_lines ol ON ol.company_id=il.company_id AND ol.id=il.order_line_id JOIN sales.line_dimensions dim ON dim.company_id=ol.company_id AND dim.order_line_id=ol.id JOIN platform.documents d ON d.company_id=i.company_id AND d.id=i.id JOIN LATERAL(SELECT*FROM sales.order_attributions WHERE company_id=o.company_id AND order_id=o.id ORDER BY version DESC LIMIT 1)a ON true
 UNION ALL
 SELECT il.company_id,'CREDIT:'||cl.id::text,CASE WHEN cl.credit_type='AMOUNT'THEN'AMOUNT_CREDIT'ELSE'QUANTITY_CREDIT'END,cn.id,cl.id,i.id,il.id,o.id,ol.id,o.customer_id,o.customer_branch_id,o.warehouse_id,ol.product_id,dim.base_uom_id,dim.base_unit_code,dim.sku,dim.product_name,a.salesperson_id,a.version,a.basis,d.business_date,-coalesce(cl.quantity,0),CASE WHEN cl.quantity IS NULL THEN 0 ELSE-cl.quantity*il.base_quantity/il.quantity END,il.quantity,il.base_quantity,-cl.net,-cl.tax,-cl.gross,cl.return_line_id,cn.created_at
 FROM sales.credit_note_lines cl JOIN sales.credit_notes cn ON cn.company_id=cl.company_id AND cn.id=cl.credit_note_id JOIN sales.invoice_lines il ON il.company_id=cl.company_id AND il.id=cl.invoice_line_id JOIN sales.invoices i ON i.company_id=il.company_id AND i.id=il.invoice_id JOIN sales.orders o ON o.company_id=i.company_id AND o.id=i.order_id JOIN sales.order_lines ol ON ol.company_id=il.company_id AND ol.id=il.order_line_id JOIN sales.line_dimensions dim ON dim.company_id=ol.company_id AND dim.order_line_id=ol.id JOIN platform.documents d ON d.company_id=cn.company_id AND d.id=cn.id JOIN LATERAL(SELECT*FROM sales.order_attributions WHERE company_id=o.company_id AND order_id=o.id ORDER BY version DESC LIMIT 1)a ON true;
CREATE VIEW sales.fulfilment_cost_source WITH(security_invoker=true)AS
 SELECT m.company_id,'ISSUE:'||m.id::text AS fact_id,pk.id AS document_id,m.id AS source_line_id,l.order_line_id,o.customer_id,ol.product_id,d.business_date AS posting_date,'STOCK_ISSUE'::text AS event_type,m.cost AS expense_cost,m.quantity AS base_quantity FROM inventory.stock_movements m JOIN inventory.pick_lines l ON l.company_id=m.company_id AND l.id=m.pick_line_id JOIN inventory.picks pk ON pk.company_id=l.company_id AND pk.id=l.pick_id JOIN sales.orders o ON o.company_id=pk.company_id AND o.id=pk.order_id JOIN sales.order_lines ol ON ol.company_id=l.company_id AND ol.id=l.order_line_id JOIN platform.documents d ON d.company_id=pk.company_id AND d.id=pk.id
 UNION ALL SELECT r.company_id,'RETURN:'||r.id::text,r.return_id,r.id,r.order_line_id,o.customer_id,ol.product_id,d.business_date,'STOCK_RETURN',-r.cost,-r.base_quantity FROM inventory.sales_return_lines r JOIN inventory.sales_returns h ON h.company_id=r.company_id AND h.id=r.return_id JOIN sales.orders o ON o.company_id=h.company_id AND o.id=h.order_id JOIN sales.order_lines ol ON ol.company_id=r.company_id AND ol.id=r.order_line_id JOIN platform.documents d ON d.company_id=r.company_id AND d.id=r.return_id
 UNION ALL SELECT v.company_id,'PURCHASE_VARIANCE:'||v.id::text,v.document_id,v.line_id,NULL,NULL,b.product_id,d.business_date,'UNALLOCATED_PURCHASE_VARIANCE',v.expense_delta,0 FROM inventory.purchase_value_adjustments v LEFT JOIN inventory.stock_balances b ON b.company_id=v.company_id AND b.id=v.stock_balance_id JOIN platform.documents d ON d.company_id=v.company_id AND d.id=v.document_id;
CREATE FUNCTION sales.validate_analytics_filter(f jsonb)RETURNS void LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();a date:=(f->>'from')::date;b date:=(f->>'to')::date;BEGIN
 IF jsonb_typeof(f)IS DISTINCT FROM'object'OR a IS NULL OR b IS NULL OR a<'0002-01-01'::date OR b<=a OR b-a>366 OR coalesce(f->>'bucket','MONTH')NOT IN('DAY','MONTH')OR EXISTS(SELECT 1 FROM jsonb_object_keys(f)k WHERE k NOT IN('from','to','customerId','branchId','productId','salespersonId','bucket'))THEN RAISE EXCEPTION 'Invalid analytics filter; use 1..366 day interval' USING ERRCODE='HR422';END IF;
 PERFORM sales.require_analytics_customer((f->>'customerId')::uuid);
 IF(f->>'branchId')IS NOT NULL AND NOT EXISTS(SELECT 1 FROM crm.customer_branches WHERE company_id=c AND id=(f->>'branchId')::uuid AND crm.mobile_customer_visible(customer_id)AND((f->>'customerId')IS NULL OR customer_id=(f->>'customerId')::uuid))THEN RAISE EXCEPTION 'Branch scope unavailable' USING ERRCODE='42501';END IF;
 IF(f->>'productId')IS NOT NULL AND NOT EXISTS(SELECT 1 FROM catalog.products WHERE company_id=c AND id=(f->>'productId')::uuid)THEN RAISE EXCEPTION 'Product unavailable' USING ERRCODE='HT404';END IF;
 IF(f->>'salespersonId')IS NOT NULL AND NOT crm.mobile_permission('reports.sales.all')AND(f->>'salespersonId')::uuid<>core.current_actor()THEN RAISE EXCEPTION 'Company attribution filter permission required' USING ERRCODE='42501';END IF;END$$;
CREATE FUNCTION sales.analytics_facts(f jsonb)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog SET jit=off AS $$DECLARE result jsonb;BEGIN PERFORM sales.validate_analytics_filter(f);
 SELECT coalesce(jsonb_agg(jsonb_build_object('factId',s.fact_id,'eventType',s.event_type,'documentId',s.document_id,'sourceLineId',s.source_line_id,'invoiceId',s.invoice_id,'invoiceLineId',s.invoice_line_id,'orderId',s.order_id,'orderLineId',s.order_line_id,'customerId',s.customer_id,'branchId',s.branch_id,'warehouseId',s.warehouse_id,'productId',s.product_id,'sku',s.sku,'productName',s.product_name,'baseUomId',s.base_uom_id,'baseUnitCode',s.base_unit_code,'salespersonId',s.salesperson_id,'attributionVersion',s.attribution_version,'attributionBasis',s.attribution_basis,'date',s.posting_date,'sellingQuantity',s.selling_quantity::text,'baseQuantity',s.base_quantity::text,'originalInvoiceQuantity',s.original_invoice_quantity::text,'originalInvoiceBaseQuantity',s.original_invoice_base_quantity::text,'net',s.net::text,'gst',s.tax::text,'gross',s.gross::text,'returnLineId',s.return_line_id)ORDER BY s.posting_date,s.fact_id),'[]')INTO result
 FROM(SELECT*FROM sales.net_sales_source s WHERE s.company_id=core.current_company()AND s.posting_date>=(f->>'from')::date AND s.posting_date<(f->>'to')::date AND sales.analytics_visible(s.customer_id)AND((f->>'customerId')IS NULL OR s.customer_id=(f->>'customerId')::uuid)AND((f->>'branchId')IS NULL OR s.branch_id=(f->>'branchId')::uuid)AND((f->>'productId')IS NULL OR s.product_id=(f->>'productId')::uuid)AND((f->>'salespersonId')IS NULL OR s.salesperson_id=(f->>'salespersonId')::uuid) ORDER BY s.posting_date,s.fact_id LIMIT 5001)s;
 IF jsonb_array_length(result)>5000 OR octet_length(result::text)>4000000 THEN RAISE EXCEPTION 'Narrow analytics interval or filters (max 5000 facts / 4 MB)' USING ERRCODE='HR422';END IF;RETURN result;END$$;
CREATE FUNCTION sales.pending_credit_returns(f jsonb)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE result jsonb;BEGIN PERFORM sales.validate_analytics_filter(f);WITH pending AS(SELECT jsonb_build_object('returnLineId',r.id,'returnId',r.return_id,'invoiceLineId',r.invoice_line_id,'orderLineId',r.order_line_id,'customerId',o.customer_id,'branchId',o.customer_branch_id,'productId',l.product_id,'baseUomId',dim.base_uom_id,'baseUnitCode',dim.base_unit_code,'date',d.business_date,'uncreditedQuantity',(r.quantity-coalesce(q.qty,0))::text,'uncreditedBaseQuantity',round((r.quantity-coalesce(q.qty,0))*r.base_quantity/r.quantity,6)::text)payload,d.business_date,r.id FROM inventory.sales_return_lines r JOIN inventory.sales_returns h ON h.company_id=r.company_id AND h.id=r.return_id JOIN platform.documents d ON d.company_id=r.company_id AND d.id=r.return_id JOIN sales.orders o ON o.company_id=h.company_id AND o.id=h.order_id JOIN sales.order_lines l ON l.company_id=r.company_id AND l.id=r.order_line_id JOIN sales.line_dimensions dim ON dim.company_id=l.company_id AND dim.order_line_id=l.id JOIN LATERAL(SELECT salesperson_id FROM sales.order_attributions WHERE company_id=o.company_id AND order_id=o.id ORDER BY version DESC LIMIT 1)a ON true LEFT JOIN LATERAL(SELECT sum(cl.quantity)qty FROM sales.credit_note_lines cl JOIN platform.documents cd ON cd.company_id=cl.company_id AND cd.id=cl.credit_note_id WHERE cl.company_id=r.company_id AND cl.return_line_id=r.id AND cd.business_date<(f->>'to')::date)q ON true
 WHERE r.company_id=core.current_company()AND r.invoice_line_id IS NOT NULL AND d.business_date<(f->>'to')::date AND r.quantity>coalesce(q.qty,0)AND sales.analytics_visible(o.customer_id)AND((f->>'customerId')IS NULL OR o.customer_id=(f->>'customerId')::uuid)AND((f->>'branchId')IS NULL OR o.customer_branch_id=(f->>'branchId')::uuid)AND((f->>'productId')IS NULL OR l.product_id=(f->>'productId')::uuid)AND((f->>'salespersonId')IS NULL OR a.salesperson_id=(f->>'salespersonId')::uuid) ORDER BY d.business_date,r.id LIMIT 5001)SELECT coalesce(jsonb_agg(payload ORDER BY business_date,id),'[]')INTO result FROM pending;IF jsonb_array_length(result)>5000 OR octet_length(result::text)>4000000 THEN RAISE EXCEPTION 'Narrow pending return filters (max 5000 rows / 4 MB)' USING ERRCODE='HR422';END IF;RETURN result;END$$;
CREATE FUNCTION sales.require_sales_reconciliation()RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM sales.require_analytics_customer(NULL);PERFORM crm.require_mobile('reports.sales.all');PERFORM crm.require_mobile('reports.sales.reconcile');PERFORM crm.require_mobile('customers.all');PERFORM crm.require_mobile('accounting.ledger.read');PERFORM crm.require_mobile('accounting.reports.read');PERFORM crm.require_mobile('inventory.cost.read');END$$;
CREATE FUNCTION sales.sales_reconciliation(p_from date,p_to date)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog SET jit=off AS $$DECLARE revenue jsonb;cost jsonb;BEGIN PERFORM sales.require_sales_reconciliation();IF p_from IS NULL OR p_to IS NULL OR p_to<=p_from OR p_to-p_from>366 THEN RAISE EXCEPTION 'Invalid reconciliation interval' USING ERRCODE='HR422';END IF;
 WITH source AS(SELECT document_id,sum(net)n FROM sales.net_sales_source WHERE company_id=core.current_company()AND posting_date>=p_from AND posting_date<p_to GROUP BY document_id),
 gl AS(SELECT b.source_document_id id,sum(l.credit-l.debit)n FROM accounting.business_journal_entries j JOIN accounting.posting_batches b ON b.company_id=j.company_id AND b.id=j.posting_batch_id JOIN accounting.journal_lines l ON l.company_id=j.company_id AND l.journal_entry_id=j.id JOIN accounting.accounts a ON a.company_id=l.company_id AND a.id=l.account_id WHERE j.company_id=core.current_company()AND j.posting_date>=p_from AND j.posting_date<p_to AND a.kind='REVENUE'GROUP BY b.source_document_id),
 source_keys AS(SELECT id FROM sales.invoices WHERE company_id=core.current_company()UNION SELECT id FROM sales.credit_notes WHERE company_id=core.current_company()),
 docs AS(SELECT coalesce(s.document_id,g.id)id,coalesce(s.n,0)expected,coalesce(g.n,0)actual FROM source s FULL JOIN(SELECT g.*FROM gl g JOIN source_keys k ON k.id=g.id)g ON g.id=s.document_id)
 SELECT jsonb_build_object('sourceNet',coalesce((SELECT sum(n)FROM source),0)::text,'invoiceCreditGl',coalesce(sum(actual),0)::text,'difference',coalesce(sum(expected-actual),0)::text,'allBusinessRevenueGl',coalesce((SELECT sum(n)FROM gl),0)::text,'otherRevenueGl',(coalesce((SELECT sum(n)FROM gl),0)-coalesce(sum(actual),0))::text,'differenceCount',count(*)FILTER(WHERE expected<>actual),'differences',coalesce(jsonb_agg(jsonb_build_object('documentId',id,'expected',expected::text,'actual',actual::text,'difference',(expected-actual)::text)ORDER BY id)FILTER(WHERE expected<>actual),'[]'),'status',CASE WHEN count(*)FILTER(WHERE expected<>actual)=0 THEN'RECONCILED'ELSE'UNRECONCILED'END)INTO revenue FROM docs;
 WITH source AS(SELECT document_id,sum(expense_cost)n FROM sales.fulfilment_cost_source WHERE company_id=core.current_company()AND posting_date>=p_from AND posting_date<p_to GROUP BY document_id),keys AS(SELECT DISTINCT document_id FROM sales.fulfilment_cost_source WHERE company_id=core.current_company()),
 gl AS(SELECT b.source_document_id id,sum(l.debit-l.credit)n FROM accounting.business_journal_entries j JOIN accounting.posting_batches b ON b.company_id=j.company_id AND b.id=j.posting_batch_id JOIN accounting.journal_lines l ON l.company_id=j.company_id AND l.journal_entry_id=j.id JOIN accounting.accounts a ON a.company_id=l.company_id AND a.id=l.account_id JOIN keys k ON k.document_id=b.source_document_id WHERE j.company_id=core.current_company()AND j.posting_date>=p_from AND j.posting_date<p_to AND a.kind='EXPENSE'GROUP BY b.source_document_id),docs AS(SELECT coalesce(s.document_id,g.id)id,coalesce(s.n,0)expected,coalesce(g.n,0)actual FROM source s FULL JOIN gl g ON s.document_id=g.id)
 SELECT jsonb_build_object('sourceExpenseCost',coalesce(sum(expected),0)::text,'glExpenseCost',coalesce(sum(actual),0)::text,'difference',coalesce(sum(expected-actual),0)::text,'differenceCount',count(*)FILTER(WHERE expected<>actual),'differences',coalesce(jsonb_agg(jsonb_build_object('documentId',id,'expected',expected::text,'actual',actual::text)ORDER BY id)FILTER(WHERE expected<>actual),'[]'),'allocationBasis','SOURCE_EVENT_NO_INVOICE_ALLOCATION','unallocatedPurchaseVariance',(SELECT coalesce(sum(expense_cost),0)::text FROM sales.fulfilment_cost_source WHERE company_id=core.current_company()AND event_type='UNALLOCATED_PURCHASE_VARIANCE'AND posting_date>=p_from AND posting_date<p_to),'status',CASE WHEN count(*)FILTER(WHERE expected<>actual)=0 THEN'RECONCILED'ELSE'UNRECONCILED'END)INTO cost FROM docs;
 RETURN jsonb_build_object('from',p_from,'to',p_to,'scope','COMPANY_WIDE','yearClosingExcluded',true,'revenue',revenue,'cost',cost,'status',CASE WHEN revenue->>'status'='RECONCILED'AND cost->>'status'='RECONCILED'THEN'RECONCILED'ELSE'UNRECONCILED'END);END$$;
CREATE FUNCTION sales.sales_comparison(current_value numeric,baseline numeric)RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT jsonb_build_object('current',current_value::text,'baseline',baseline::text,'change',(current_value-baseline)::text,'percent',CASE WHEN baseline>0 THEN round((current_value-baseline)/baseline*100,4)::text ELSE NULL END,'status',CASE WHEN baseline=0 THEN'NO_BASELINE'WHEN baseline<0 THEN'NEGATIVE_BASELINE'ELSE'COMPARABLE'END)$$;
CREATE FUNCTION sales.analytics_year_date(d date)RETURNS date LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$SELECT CASE WHEN extract(month FROM d)=2 AND extract(day FROM d)=29 THEN make_date(extract(year FROM d)::int-1,3,1)ELSE(d-interval '1 year')::date END$$;
REVOKE ALL ON FUNCTION sales.analytics_year_date(date)FROM PUBLIC;
CREATE FUNCTION sales.build_sales_series(data jsonb,first_date date,last_date date,buck text)RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$DECLARE dims int;points int;rows jsonb;step interval:=CASE buck WHEN'DAY'THEN interval '1 day'ELSE interval '1 month'END;BEGIN IF first_date IS NULL OR last_date IS NULL OR last_date<=first_date OR last_date-first_date>366 OR buck IS NULL OR buck NOT IN('DAY','MONTH')THEN RAISE EXCEPTION 'Invalid series interval' USING ERRCODE='HR422';END IF;
 SELECT count(*)INTO dims FROM(SELECT DISTINCT e->>'customerId',e->>'branchId',e->>'productId',e->>'baseUomId'FROM jsonb_array_elements(data)e)d;SELECT count(*)INTO points FROM generate_series(date_trunc(lower(buck),first_date::timestamp),date_trunc(lower(buck),(last_date-1)::timestamp),step);
 IF dims::bigint*points>5000 THEN RAISE EXCEPTION 'Trend too large; narrow customer/product/date filters' USING ERRCODE='HR422';END IF;
 WITH facts AS MATERIALIZED(SELECT e,(e->>'date')::date d,(e->>'net')::numeric n,(e->>'baseQuantity')::numeric q FROM jsonb_array_elements(data)e),dimensions AS(SELECT e->>'customerId'customer,e->>'branchId'branch,e->>'productId'product,e->>'baseUomId'uom,min(e->>'sku')sku,min(e->>'productName')name,min(e->>'baseUnitCode')code FROM facts GROUP BY 1,2,3,4),buckets AS(SELECT greatest(g::date,first_date)a,least((g+step)::date,last_date)b FROM generate_series(date_trunc(lower(buck),first_date::timestamp),date_trunc(lower(buck),(last_date-1)::timestamp),step)g),cells AS(
 SELECT d.*,b.a,b.b,coalesce(sum(x.n)FILTER(WHERE x.d>=b.a AND x.d<b.b),0)current_net,coalesce(sum(x.n)FILTER(WHERE x.d>=(b.a-step)::date AND x.d<(b.b-step)::date),0)prior_net,coalesce(sum(x.n)FILTER(WHERE x.d>=sales.analytics_year_date(b.a) AND x.d<sales.analytics_year_date(b.b)),0)year_net,round(coalesce(sum(x.q)FILTER(WHERE x.d>=b.a AND x.d<b.b),0),6)current_qty,round(coalesce(sum(x.q)FILTER(WHERE x.d>=(b.a-step)::date AND x.d<(b.b-step)::date),0),6)prior_qty,round(coalesce(sum(x.q)FILTER(WHERE x.d>=sales.analytics_year_date(b.a) AND x.d<sales.analytics_year_date(b.b)),0),6)year_qty
 FROM dimensions d CROSS JOIN buckets b LEFT JOIN facts x ON x.e->>'customerId'=d.customer AND x.e->>'branchId'=d.branch AND x.e->>'productId'=d.product AND x.e->>'baseUomId'=d.uom GROUP BY d.customer,d.branch,d.product,d.uom,d.sku,d.name,d.code,b.a,b.b)
 SELECT coalesce(jsonb_agg(jsonb_build_object('from',a,'to',b,'customerId',customer,'branchId',branch,'productId',product,'sku',sku,'productName',name,'baseUomId',uom,'baseUnitCode',code,'net',current_net::text,'previousNet',prior_net::text,'yearAgoNet',year_net::text,'previousChangePercent',CASE WHEN prior_net>0 THEN round((current_net-prior_net)/prior_net*100,4)::text ELSE NULL END,'yearChangePercent',CASE WHEN year_net>0 THEN round((current_net-year_net)/year_net*100,4)::text ELSE NULL END,'baseQuantity',current_qty::text,'previousBaseQuantity',prior_qty::text,'yearAgoBaseQuantity',year_qty::text,'previousBucket',sales.sales_comparison(current_net,prior_net),'yearAgo',sales.sales_comparison(current_net,year_net)||CASE WHEN sales.analytics_year_date(a)=sales.analytics_year_date(b)THEN jsonb_build_object('status','NO_CALENDAR_EQUIVALENT')ELSE'{}'::jsonb END)ORDER BY a,customer,branch,product,uom),'[]')INTO rows FROM cells;
 RETURN rows;END$$;
REVOKE ALL ON FUNCTION sales.build_sales_series(jsonb,date,date,text)FROM PUBLIC;
CREATE FUNCTION sales.analytics_report(f jsonb)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog SET jit=off AS $$DECLARE cur jsonb;prev jsonb;yearago jsonb;prior_bucket_facts jsonb;data jsonb;pending jsonb;rows jsonb;units jsonb;first_date date;last_date date;prev_from date;prev_to date;year_from date;year_to date;buck text:=coalesce(f->>'bucket','MONTH');step interval;dims int;points int;net numeric;previous_net numeric;year_net numeric;tax numeric;gross numeric;bridge jsonb;result jsonb;BEGIN
 PERFORM sales.validate_analytics_filter(f);first_date:=(f->>'from')::date;last_date:=(f->>'to')::date;IF first_date<'0003-01-01'::date THEN RAISE EXCEPTION 'Comparative reporting begins in year 3' USING ERRCODE='HR422';END IF;
 IF date_trunc('month',first_date)=first_date::timestamp AND date_trunc('month',last_date)=last_date::timestamp THEN prev_from:=(first_date-make_interval(months=>(extract(year FROM age(last_date,first_date))*12+extract(month FROM age(last_date,first_date)))::int))::date;ELSE prev_from:=first_date-(last_date-first_date);END IF;prev_to:=first_date;
 cur:=sales.analytics_facts(f);prev:=sales.analytics_facts(f||jsonb_build_object('from',prev_from,'to',prev_to));year_from:=sales.analytics_year_date(first_date);year_to:=sales.analytics_year_date(last_date);yearago:=CASE WHEN year_to=year_from THEN'[]'::jsonb ELSE sales.analytics_facts(f||jsonb_build_object('from',year_from,'to',year_to))END;step:=CASE buck WHEN'DAY'THEN interval '1 day'ELSE interval '1 month'END;
 prior_bucket_facts:=sales.analytics_facts(f||jsonb_build_object('from',(first_date-step)::date,'to',first_date));SELECT coalesce(jsonb_agg(e ORDER BY e->>'date',e->>'factId'),'[]')INTO data FROM(SELECT DISTINCT ON(e->>'factId')e FROM jsonb_array_elements(cur||prev||yearago||prior_bucket_facts)e ORDER BY e->>'factId')q;
 rows:=sales.build_sales_series(data,first_date,last_date,buck);
 SELECT coalesce(sum((e->>'net')::numeric),0),coalesce(sum((e->>'gst')::numeric),0),coalesce(sum((e->>'gross')::numeric),0)INTO net,tax,gross FROM jsonb_array_elements(cur)e;SELECT coalesce(sum((e->>'net')::numeric),0)INTO previous_net FROM jsonb_array_elements(prev)e;SELECT coalesce(sum((e->>'net')::numeric),0)INTO year_net FROM jsonb_array_elements(yearago)e;
 SELECT coalesce(jsonb_agg(jsonb_build_object('baseUomId',id,'baseUnitCode',code,'baseQuantity',qty::text)ORDER BY id),'[]')INTO units FROM(SELECT e->>'baseUomId'id,min(e->>'baseUnitCode')code,round(sum((e->>'baseQuantity')::numeric),6)qty FROM jsonb_array_elements(cur)e GROUP BY 1)q;
 pending:=sales.pending_credit_returns(f);IF jsonb_array_length(pending)>5000 THEN RAISE EXCEPTION 'Too many pending returns; narrow filters' USING ERRCODE='HR422';END IF;
 result:=jsonb_build_object('kind','SALES','schemaVersion',1,'companyId',core.current_company(),'currency','AUD','basis','POSTING_DATE','snapshotAt',statement_timestamp(),'mvccSnapshot',txid_current_snapshot()::text,'from',first_date,'to',last_date,'filters',f,'bucket',buck,'sourceFactCount',jsonb_array_length(cur),'sourceFacts',cur,'sourceHash',encode(sha256(convert_to(cur::text,'UTF8')),'hex'),'rows',rows,'totals',jsonb_build_object('net',net::text,'gst',tax::text,'gross',gross::text,'quantityByBaseUnit',units,'previousPeriod',sales.sales_comparison(net,previous_net)||jsonb_build_object('from',prev_from,'to',prev_to),'yearAgo',sales.sales_comparison(net,year_net)||jsonb_build_object('from',year_from,'to',year_to,'status',CASE WHEN year_from=year_to THEN'NO_CALENDAR_EQUIVALENT'WHEN year_net=0 THEN'NO_BASELINE'WHEN year_net<0 THEN'NEGATIVE_BASELINE'ELSE'COMPARABLE'END)),'pendingReturns',pending,'pendingReturnsBasis','AS_OF_TO_EXCLUSIVE_QUANTITY_CREDITS_ONLY','quantityRounding','SUM_IN_BASE_UNIT_THEN_6DP','status','SOURCE_FACTS');
 IF octet_length(result::text)>4000000 THEN RAISE EXCEPTION 'Analytics output too large; narrow filters' USING ERRCODE='HR422';END IF;RETURN result;
END$$;
ALTER TABLE accounting.operating_report_runs DROP CONSTRAINT operating_report_runs_kind_check;
ALTER TABLE accounting.operating_report_runs ADD CONSTRAINT operating_report_runs_kind_check CHECK(kind IN('PURCHASING','ARAP','INVENTORY','BANKING','SALES'));

CREATE OR REPLACE FUNCTION accounting.require_operating_report(p_kind text)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 PERFORM purchase.require_access('reports.operating.read');PERFORM purchase.require_access('accounting.ledger.read');PERFORM purchase.require_access('accounting.reports.read');
 IF p_kind='PURCHASING'THEN PERFORM purchase.require_access('purchase.orders.read');PERFORM purchase.require_access('purchase.cost.read');
 ELSIF p_kind='INVENTORY'THEN PERFORM purchase.require_access('inventory.cost.read');
 ELSIF p_kind='ARAP'THEN PERFORM purchase.require_access('customers.all');
 ELSIF p_kind='SALES'THEN PERFORM sales.require_sales_reconciliation();PERFORM crm.require_mobile('customers.all');
 ELSIF p_kind='BANKING'THEN PERFORM purchase.require_access('accounting.banks.read');PERFORM purchase.require_access('accounting.bank_statements.read');
 ELSE RAISE EXCEPTION 'Unknown operating report' USING ERRCODE='HR422';END IF;
END$$;
CREATE OR REPLACE FUNCTION accounting.operating_report(p_kind text,p_from date,p_to date,p_party uuid DEFAULT NULL,p_warehouse uuid DEFAULT NULL,p_bank uuid DEFAULT NULL)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog SET jit=off AS $$
DECLARE c uuid:=core.current_company();result jsonb;f jsonb;BEGIN
 PERFORM accounting.require_operating_report(p_kind);
 IF p_from IS NULL OR p_from<'0002-01-01'OR p_to IS NULL OR p_to<=p_from OR p_to-p_from>366 OR p_party IS NOT NULL AND p_kind NOT IN('ARAP','PURCHASING')OR p_warehouse IS NOT NULL AND p_kind<>'INVENTORY'OR p_bank IS NOT NULL AND p_kind<>'BANKING'THEN RAISE EXCEPTION 'Invalid report range or unsupported filter' USING ERRCODE='HR422';END IF;
 IF p_party IS NOT NULL AND NOT EXISTS(SELECT 1 FROM crm.parties WHERE company_id=c AND id=p_party)OR p_warehouse IS NOT NULL AND NOT EXISTS(SELECT 1 FROM catalog.warehouses WHERE company_id=c AND id=p_warehouse)OR p_bank IS NOT NULL AND NOT EXISTS(SELECT 1 FROM accounting.bank_accounts WHERE company_id=c AND id=p_bank)THEN RAISE EXCEPTION 'Report filter unavailable' USING ERRCODE='HT404';END IF;
 IF p_kind='SALES'THEN IF p_party IS NOT NULL OR p_warehouse IS NOT NULL OR p_bank IS NOT NULL THEN RAISE EXCEPTION 'Use sales analytics filters for dimension reports' USING ERRCODE='HR422';END IF;RETURN sales.analytics_report(jsonb_build_object('from',p_from,'to',p_to,'bucket','MONTH'))||jsonb_build_object('reconciliation',sales.sales_reconciliation(p_from,p_to));END IF;
 IF p_kind='PURCHASING'THEN
 WITH events AS MATERIALIZED(
 SELECT o.id,o.supplier_id,s.party_id,o.warehouse_id,d.business_date AS occurred_on,d.number,'ORDER'::text AS event_type,o.net,o.tax,o.gross FROM purchase.orders o JOIN platform.documents d ON d.company_id=o.company_id AND d.id=o.id JOIN crm.suppliers s ON s.company_id=o.company_id AND s.id=o.supplier_id WHERE o.company_id=c AND o.status<>'DRAFT'
 UNION ALL SELECT r.id,r.supplier_id,s.party_id,r.warehouse_id,d.business_date,d.number,'RECEIPT',sum(l.valuation_amount),0,sum(l.valuation_amount)FROM purchase.receipts r JOIN purchase.receipt_lines l ON l.company_id=r.company_id AND l.receipt_id=r.id JOIN platform.documents d ON d.company_id=r.company_id AND d.id=r.id JOIN crm.suppliers s ON s.company_id=r.company_id AND s.id=r.supplier_id WHERE r.company_id=c GROUP BY r.id,s.party_id,d.business_date,d.number
 UNION ALL SELECT r.id,r.supplier_id,s.party_id,r.warehouse_id,d.business_date,d.number,'RETURN',-sum(l.cost),0,-sum(l.cost)FROM purchase.returns r JOIN purchase.return_lines l ON l.company_id=r.company_id AND l.return_id=r.id JOIN platform.documents d ON d.company_id=r.company_id AND d.id=r.id JOIN crm.suppliers s ON s.company_id=r.company_id AND s.id=r.supplier_id WHERE r.company_id=c GROUP BY r.id,s.party_id,d.business_date,d.number
 UNION ALL SELECT b.id,b.supplier_id,b.party_id,NULL,d.business_date,d.number,'BILL',b.net,b.tax,b.gross FROM purchase.bills b JOIN platform.documents d ON d.company_id=b.company_id AND d.id=b.id WHERE b.company_id=c
 UNION ALL SELECT b.id,b.supplier_id,s.party_id,NULL,d.business_date,d.number,'CREDIT',-b.net,-b.tax,-b.gross FROM purchase.supplier_credit_notes b JOIN platform.documents d ON d.company_id=b.company_id AND d.id=b.id JOIN crm.suppliers s ON s.company_id=b.company_id AND s.id=b.supplier_id WHERE b.company_id=c), scoped AS MATERIALIZED(SELECT e.*,p.legal_name FROM events e JOIN crm.parties p ON p.company_id=c AND p.id=e.party_id WHERE e.occurred_on>=p_from AND e.occurred_on<p_to AND(p_party IS NULL OR e.party_id=p_party))
 SELECT jsonb_build_object('rows',coalesce(jsonb_agg(jsonb_build_object('documentId',id,'number',number,'date',occurred_on,'eventType',event_type,'supplierId',supplier_id,'partyName',legal_name,'warehouseId',warehouse_id,'net',net::text,'gst',tax::text,'gross',gross::text)ORDER BY occurred_on,id),'[]'),'totals',jsonb_build_object('orderCommitments',coalesce(sum(gross)FILTER(WHERE event_type='ORDER'),0)::text,'receiptsCost',coalesce(sum(gross)FILTER(WHERE event_type='RECEIPT'),0)::text,'returnedCost',coalesce(sum(gross)FILTER(WHERE event_type='RETURN'),0)::text,'netReceiptsCost',coalesce(sum(gross)FILTER(WHERE event_type IN('RECEIPT','RETURN')),0)::text,'bills',coalesce(sum(gross)FILTER(WHERE event_type='BILL'),0)::text,'credits',coalesce(sum(gross)FILTER(WHERE event_type='CREDIT'),0)::text,'netBilled',coalesce(sum(gross)FILTER(WHERE event_type IN('BILL','CREDIT')),0)::text),'status','SOURCE_EVENTS')INTO result FROM scoped;
 ELSIF p_kind IN('ARAP','INVENTORY')THEN
 f:=accounting.close_financials(p_from,p_to);
 IF p_kind='ARAP'THEN
 WITH gl AS(SELECT e->>'controlKind'AS side,nullif(e->>'partyId','')::uuid AS party_id,sum(CASE WHEN e->>'controlKind'='AR'THEN(e->>'balance')::numeric ELSE-(e->>'balance')::numeric END)AS closing,sum(CASE WHEN e->>'controlKind'='AR'THEN(e->>'opening')::numeric ELSE-(e->>'opening')::numeric END)AS opening,sum((e->>'periodDebit')::numeric)AS debits,sum((e->>'periodCredit')::numeric)AS credits FROM jsonb_array_elements(f->'gl')e WHERE e->>'controlKind'IN('AR','AP')GROUP BY 1,2),
 items AS(SELECT e->>'side'AS side,(e->>'partyId')::uuid AS party_id,sum((e->>'balance')::numeric)AS balance FROM jsonb_array_elements(f->'openItems')e GROUP BY 1,2),
 adv AS(SELECT side,party_id,sum(amount)AS advance FROM accounting.report_advance_events WHERE company_id=c AND posting_date<p_to GROUP BY side,party_id),keys AS(SELECT side,party_id FROM gl UNION SELECT side,party_id FROM items UNION SELECT side,party_id FROM adv), rows AS(SELECT k.side,k.party_id,p.legal_name,coalesce(g.opening,0)AS opening,coalesce(g.debits,0)AS debits,coalesce(g.credits,0)AS credits,coalesce(g.closing,0)AS closing,coalesce(i.balance,0)AS business,coalesce(a.advance,0)AS advance FROM keys k LEFT JOIN gl g ON g.side=k.side AND g.party_id IS NOT DISTINCT FROM k.party_id LEFT JOIN items i ON i.side=k.side AND i.party_id IS NOT DISTINCT FROM k.party_id LEFT JOIN adv a ON a.side=k.side AND a.party_id IS NOT DISTINCT FROM k.party_id LEFT JOIN crm.parties p ON p.company_id=c AND p.id=k.party_id WHERE(p_party IS NULL OR k.party_id=p_party))
 SELECT jsonb_build_object('rows',coalesce(jsonb_agg(jsonb_build_object('side',side,'partyId',party_id,'partyName',legal_name,'opening',opening::text,'debits',debits::text,'credits',credits::text,'closing',closing::text,'businessBalance',business::text,'difference',(closing-business)::text,'advanceBalance',advance::text)ORDER BY side,party_id),'[]'),'totals',jsonb_build_object('receivables',coalesce(sum(closing)FILTER(WHERE side='AR'),0)::text,'payables',coalesce(sum(closing)FILTER(WHERE side='AP'),0)::text,'customerAdvances',coalesce(sum(advance)FILTER(WHERE side='AR'),0)::text,'supplierAdvances',coalesce(sum(advance)FILTER(WHERE side='AP'),0)::text,'differenceCount',count(*)FILTER(WHERE closing<>business)),'status',CASE WHEN count(*)FILTER(WHERE closing<>business)=0 THEN'RECONCILED'ELSE'UNRECONCILED'END)INTO result FROM rows;
 ELSE
 WITH stock AS(SELECT e FROM jsonb_array_elements(f->'inventory')e WHERE p_warehouse IS NULL OR(e->>'warehouseId')::uuid=p_warehouse), rows AS(SELECT e||jsonb_build_object('positionType','ON_HAND','sku',p.sku,'name',p.name)AS row FROM stock JOIN catalog.products p ON p.company_id=c AND p.id=(e->>'productId')::uuid), transit AS(SELECT e||jsonb_build_object('positionType','IN_TRANSIT','warehouseId',h.destination_id,'sourceWarehouseId',h.source_id,'productId',l.product_id,'sku',p.sku,'name',p.name)AS row FROM jsonb_array_elements(f->'transit')e JOIN inventory.transit_transfer_lines l ON l.company_id=c AND l.id=(e->>'lineId')::uuid JOIN inventory.transit_transfers h ON h.company_id=l.company_id AND h.id=l.transfer_id JOIN catalog.products p ON p.company_id=l.company_id AND p.id=l.product_id WHERE p_warehouse IS NULL OR h.destination_id=p_warehouse),combined AS(SELECT row FROM rows UNION ALL SELECT row FROM transit)
 SELECT jsonb_build_object('rows',coalesce(jsonb_agg(row ORDER BY row->>'positionType',row->>'warehouseId',row->>'productId',row->>'stockBalanceId',row->>'lineId'),'[]'),'totals',jsonb_build_object('onHandValue',coalesce(sum((row->>'value')::numeric)FILTER(WHERE row->>'positionType'='ON_HAND'),0)::text,'inTransitValue',coalesce(sum((row->>'value')::numeric)FILTER(WHERE row->>'positionType'='IN_TRANSIT'),0)::text),'companyInventoryDifference',f->'inventoryDifference','controlCheckScope','COMPANY_WIDE','transitWarehouseBasis','DESTINATION','status',CASE WHEN(f->>'inventoryDifference')::numeric=0 THEN'RECONCILED'ELSE'UNRECONCILED'END)INTO result FROM combined;
 END IF;
 ELSE
 WITH gl AS MATERIALIZED(SELECT b.id,b.name,coalesce(sum(l.debit-l.credit)FILTER(WHERE j.posting_date<p_from),0)AS opening,coalesce(sum(l.debit)FILTER(WHERE j.posting_date>=p_from AND j.posting_date<p_to),0)AS debits,coalesce(sum(l.credit)FILTER(WHERE j.posting_date>=p_from AND j.posting_date<p_to),0)AS credits,coalesce(sum(l.debit-l.credit)FILTER(WHERE j.posting_date<p_to),0)AS closing FROM accounting.bank_accounts b LEFT JOIN accounting.journal_lines l ON l.company_id=b.company_id AND l.account_id=b.id LEFT JOIN accounting.journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id WHERE b.company_id=c AND(p_bank IS NULL OR b.id=p_bank)GROUP BY b.id),rows AS(SELECT g.*,coalesce((SELECT sum(p.amount-p.reserved_amount)FROM accounting.bank_cash_positions p WHERE p.company_id=c AND p.bank_account_id=g.id AND p.posting_date<p_to),0)AS unallocated_cash,coalesce((SELECT sum(abs(l.amount)-coalesce((SELECT sum(a.amount)FROM accounting.active_bank_matches m JOIN accounting.bank_match_allocations a ON a.company_id=m.company_id AND a.match_id=m.id WHERE m.company_id=c AND m.statement_line_id=l.id),0))FROM accounting.bank_statement_lines l JOIN accounting.bank_statement_controls sc ON sc.company_id=l.company_id AND sc.id=l.statement_id WHERE l.company_id=c AND l.bank_account_id=g.id AND sc.state='OPEN'AND l.transaction_date>=p_from AND l.transaction_date<p_to),0)AS unmatched_statements,(SELECT max(to_date)FROM accounting.active_bank_reconciliations WHERE company_id=c AND bank_account_id=g.id AND to_date<p_to)AS reconciled_to FROM gl g)
 SELECT jsonb_build_object('rows',coalesce(jsonb_agg(jsonb_build_object('bankAccountId',id,'bankName',name,'opening',opening::text,'debits',debits::text,'credits',credits::text,'closing',closing::text,'unallocatedCash',unallocated_cash::text,'unmatchedStatements',unmatched_statements::text,'lastReconciledTo',reconciled_to)ORDER BY id),'[]'),'totals',jsonb_build_object('opening',coalesce(sum(opening),0)::text,'debits',coalesce(sum(debits),0)::text,'credits',coalesce(sum(credits),0)::text,'closing',coalesce(sum(closing),0)::text),'clearingBasis','CURRENT_AT_CAPTURE','status','GL_BALANCES')INTO result FROM rows;
 END IF;
 IF p_kind='ARAP'THEN f:=accounting.advance_control_check(p_to);result:=result||jsonb_build_object('advanceControl',f);IF(f->>'customerDifference')::numeric<>0 OR(f->>'supplierDifference')::numeric<>0 THEN result:=result||jsonb_build_object('status','UNRECONCILED');END IF;END IF;
 IF jsonb_array_length(result->'rows')>5000 OR octet_length(result::text)>4000000 THEN RAISE EXCEPTION 'Report too large; narrow range or filter' USING ERRCODE='HR422';END IF;
 RETURN result||jsonb_build_object('companyId',c,'kind',p_kind,'currency','AUD','basis','POSTING_DATE','from',p_from,'to',p_to,'snapshotAt',statement_timestamp(),'filters',jsonb_build_object('partyId',p_party,'warehouseId',p_warehouse,'bankAccountId',p_bank));
END$$;
CREATE OR REPLACE FUNCTION accounting.report_export_payload(p_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE r accounting.operating_report_runs;BEGIN SELECT*INTO r FROM accounting.operating_report_runs WHERE company_id=core.current_company()AND id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Report unavailable' USING ERRCODE='HT404';END IF;PERFORM platform.require_document_access(p_id,'EXPORT');RETURN r.snapshot||jsonb_build_object('snapshotHash',r.sha256,'filename','RP-'||r.id::text||'.csv','columns',('{"PURCHASING":[{"key":"date","label":"Date","type":"text"},{"key":"eventType","label":"Event","type":"text"},{"key":"number","label":"Document","type":"text"},{"key":"supplierId","label":"Supplier ID","type":"text"},{"key":"partyName","label":"Supplier","type":"text"},{"key":"warehouseId","label":"Warehouse ID","type":"text"},{"key":"net","label":"Net AUD","type":"decimal"},{"key":"gst","label":"GST AUD","type":"decimal"},{"key":"gross","label":"Gross AUD","type":"decimal"}],"ARAP":[{"key":"side","label":"Side","type":"text"},{"key":"partyId","label":"Party ID","type":"text"},{"key":"partyName","label":"Party","type":"text"},{"key":"opening","label":"Opening AUD","type":"decimal"},{"key":"debits","label":"Debits AUD","type":"decimal"},{"key":"credits","label":"Credits AUD","type":"decimal"},{"key":"closing","label":"Closing AUD","type":"decimal"},{"key":"businessBalance","label":"Business balance AUD","type":"decimal"},{"key":"difference","label":"Difference AUD","type":"decimal"},{"key":"advanceBalance","label":"Advance AUD","type":"decimal"}],"INVENTORY":[{"key":"positionType","label":"Position","type":"text"},{"key":"warehouseId","label":"Warehouse ID","type":"text"},{"key":"productId","label":"Product ID","type":"text"},{"key":"sku","label":"SKU","type":"text"},{"key":"name","label":"Product","type":"text"},{"key":"openingQuantity","label":"Opening qty","type":"decimal"},{"key":"quantityIn","label":"Qty in","type":"decimal"},{"key":"quantityOut","label":"Qty out","type":"decimal"},{"key":"quantity","label":"Closing qty","type":"decimal"},{"key":"openingValue","label":"Opening AUD","type":"decimal"},{"key":"valueIn","label":"Value in AUD","type":"decimal"},{"key":"valueOut","label":"Value out AUD","type":"decimal"},{"key":"value","label":"Closing AUD","type":"decimal"}],"BANKING":[{"key":"bankAccountId","label":"Bank ID","type":"text"},{"key":"bankName","label":"Bank","type":"text"},{"key":"opening","label":"Opening AUD","type":"decimal"},{"key":"debits","label":"Debits AUD","type":"decimal"},{"key":"credits","label":"Credits AUD","type":"decimal"},{"key":"closing","label":"Closing AUD","type":"decimal"},{"key":"unallocatedCash","label":"Unallocated cash AUD","type":"decimal"},{"key":"unmatchedStatements","label":"Unmatched statement AUD","type":"decimal"},{"key":"lastReconciledTo","label":"Reconciled to","type":"text"}],"SALES":[{"key":"from","label":"From","type":"text"},{"key":"to","label":"To exclusive","type":"text"},{"key":"customerId","label":"Customer ID","type":"text"},{"key":"branchId","label":"Branch ID","type":"text"},{"key":"productId","label":"Product ID","type":"text"},{"key":"sku","label":"SKU","type":"text"},{"key":"productName","label":"Product","type":"text"},{"key":"baseUomId","label":"Base UOM ID","type":"text"},{"key":"baseUnitCode","label":"Base unit","type":"text"},{"key":"net","label":"Net sales AUD","type":"decimal"},{"key":"baseQuantity","label":"Base quantity","type":"decimal"},{"key":"previousBaseQuantity","label":"Previous quantity","type":"decimal"},{"key":"yearAgoBaseQuantity","label":"Year ago quantity","type":"decimal"},{"key":"previousNet","label":"Previous net AUD","type":"decimal"},{"key":"yearAgoNet","label":"Year ago net AUD","type":"decimal"},{"key":"previousChangePercent","label":"Previous change percent","type":"decimal"},{"key":"yearChangePercent","label":"Year ago change percent","type":"decimal"}]}'::jsonb)->r.kind);END$$;

CREATE FUNCTION sales.capture_analytics(f jsonb)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE id uuid:=gen_random_uuid();body jsonb;BEGIN PERFORM accounting.require_operating_report('SALES');PERFORM sales.validate_analytics_filter(f);SELECT sales.analytics_report(f)||jsonb_build_object('reconciliation',sales.sales_reconciliation((f->>'from')::date,(f->>'to')::date))INTO body;IF octet_length(body::text)>4000000 THEN RAISE EXCEPTION 'Checkpoint too large; narrow filters' USING ERRCODE='HR422';END IF;
 INSERT INTO platform.documents(id,company_id,document_type,number,business_date,state,created_by)VALUES(id,core.current_company(),'OPERATING_REPORT','RP-'||id::text,(f->>'to')::date-1,'CONFIRMED',core.current_actor());
 INSERT INTO accounting.operating_report_runs(id,company_id,kind,from_date,to_date,filters,snapshot,sha256,created_by)VALUES(id,core.current_company(),'SALES',(f->>'from')::date,(f->>'to')::date,f,body,encode(sha256(convert_to(body::text,'UTF8')),'hex'),core.current_actor());RETURN id;END$$;
CREATE FUNCTION sales.checkpoint_json(p_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE r accounting.operating_report_runs;BEGIN PERFORM accounting.require_operating_report('SALES');SELECT*INTO r FROM accounting.operating_report_runs WHERE company_id=core.current_company()AND id=p_id AND kind='SALES';IF NOT FOUND THEN RAISE EXCEPTION 'Sales checkpoint unavailable' USING ERRCODE='HT404';END IF;RETURN jsonb_build_object('id',r.id,'version',1,'sha256',r.sha256,'snapshot',r.snapshot,'createdAt',r.created_at);END$$;
DO $$DECLARE p record;BEGIN FOR p IN SELECT oid::regprocedure AS fn FROM pg_proc WHERE pronamespace='sales'::regnamespace AND proname=ANY(ARRAY['capture_order_attribution','capture_line_dimension','require_analytics_customer','analytics_visible','attribution_view','assign_attribution','validate_analytics_filter','analytics_facts','pending_credit_returns','require_sales_reconciliation','sales_reconciliation','sales_comparison','analytics_report','capture_analytics','checkpoint_json'])LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',p.fn);END LOOP;END$$;
REVOKE ALL ON FUNCTION identity.seed_sales_analytics_roles(uuid)FROM PUBLIC;
GRANT EXECUTE ON FUNCTION sales.require_analytics_customer(uuid),sales.attribution_view(uuid),sales.assign_attribution(uuid,bigint,uuid,text),sales.analytics_facts(jsonb),sales.pending_credit_returns(jsonb),sales.sales_reconciliation(date,date),sales.analytics_report(jsonb),sales.capture_analytics(jsonb),sales.checkpoint_json(uuid)TO htt_app;
CREATE FUNCTION sales.require_attribution_actor(p_order uuid,p_user uuid)RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE cust uuid;BEGIN PERFORM crm.require_mobile('sales.attribution.assign');PERFORM sales.attribution_view(p_order);SELECT customer_id INTO cust FROM sales.orders WHERE company_id=core.current_company()AND id=p_order;IF NOT crm.member_permission(p_user,'reports.sales.read')OR NOT crm.member_customer(p_user,cust)THEN RAISE EXCEPTION 'Salesperson access changed' USING ERRCODE='42501';END IF;END$$;
REVOKE ALL ON FUNCTION sales.require_attribution_actor(uuid,uuid)FROM PUBLIC;GRANT EXECUTE ON FUNCTION sales.require_attribution_actor(uuid,uuid)TO htt_app;

CREATE FUNCTION sales.guard_attribution_freeze()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE v bigint;BEGIN PERFORM 1 FROM platform.documents WHERE company_id=NEW.company_id AND id=NEW.order_id FOR UPDATE;SELECT max(version)INTO v FROM sales.order_attributions WHERE company_id=NEW.company_id AND order_id=NEW.order_id;
 IF NEW.version=1 THEN IF v IS NOT NULL THEN RAISE EXCEPTION 'Attribution already initialized' USING ERRCODE='23514';END IF;
 ELSE IF NEW.version IS DISTINCT FROM v+1 OR NEW.basis<>'EXPLICIT'OR EXISTS(SELECT 1 FROM sales.invoices WHERE company_id=NEW.company_id AND order_id=NEW.order_id)OR EXISTS(SELECT 1 FROM sales.orders WHERE company_id=NEW.company_id AND id=NEW.order_id AND cancelled_at IS NOT NULL)THEN RAISE EXCEPTION 'Attribution cannot change after invoicing or cancellation' USING ERRCODE='23514';END IF;PERFORM crm.require_mobile('sales.attribution.assign');END IF;RETURN NEW;END$$;
CREATE TRIGGER attribution_freeze BEFORE INSERT ON sales.order_attributions FOR EACH ROW EXECUTE FUNCTION sales.guard_attribution_freeze();
REVOKE ALL ON FUNCTION sales.guard_attribution_freeze()FROM PUBLIC;
